def maxMoves(kx: int, ky: int, positions: List[List[int]]):
    n = len(positions)

    # Calculate knight distance from (sx, sy) to (tx, ty)
    def knight_dist(sx, sy, tx, ty):
        dx = abs(tx - sx)
        dy = abs(ty - sy)
        if dx < dy:
            dx, dy = dy, dx
        if dx == 1 and dy == 0:
            return 3
        if dx == 2 and dy == 2:
            return 4
        return max((dx + 1) // 2, (dx + dy + 2) // 3)

    # Precompute distances from start and between all pawns
    # dist_start[i] = distance from knight start to pawn i
    # dist_between[i][j] = distance from pawn i to pawn j
    dist_start = [knight_dist(kx, ky, positions[i][0], positions[i][1]) for i in range(n)]
    dist_between = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                dist_between[i][j] = knight_dist(positions[i][0], positions[i][1], positions[j][0], positions[j][1])

    from functools import lru_cache

    # State: (mask, last) where mask is bitmask of remaining pawns, last is the index of the last captured pawn (or -1 for start)
    # We use memoization. mask has n bits, bit i set means pawn i still exists.
    # last: -1 means knight is at start position, otherwise last is the index of the last captured pawn (knight is currently there)

    @lru_cache(maxsize=None)
    def dp(mask, last):
        """
        Returns the maximum total moves from this state onwards, assuming both play optimally.
        Alice maximizes, Bob minimizes.
        We need to know whose turn it is. We can determine it from the number of pawns captured so far.
        Total pawns = n. Captured = n - popcount(mask).
        If captured is even, it's Alice's turn (Alice goes first, so 0 captured -> Alice).
        If captured is odd, it's Bob's turn.
        """
        if mask == 0:
            return 0

        captured = n - bin(mask).count('1')
        alice_turn = (captured % 2 == 0)

        best = None
        for i in range(n):
            if mask & (1 << i):
                # Player captures pawn i
                if last == -1:
                    cost = dist_start[i]
                else:
                    cost = dist_between[last][i]

                new_mask = mask ^ (1 << i)
                sub = dp(new_mask, i)

                val = cost + sub
                if best is None:
                    best = val
                elif alice_turn:
                    best = max(best, val)
                else:
                    best = min(best, val)

        return best

    return dp((1 << n) - 1, -1)
