            prefix_max[i] = max(prefix_max[i-1], dp[k-1][i])

        for i in range(n):
            l_i = indexed[i][1]
            pos = bisect_left(right_endpoints, l_i)
            if pos == 0:
                dp[k][i] = -1
            else:
                best_prev = prefix_max[pos - 1]
                if best_prev >= 0:
                    dp[k][i] = indexed[i][2] + best_prev
                else:
                    dp[k][i] = -1

    max_weight = 0
    for k in range(1, MAX_K + 1):
        for i in range(n):
