                valid_ends.append((k, i))

    best_result = None

    for k, end_i in valid_ends:
        path = [end_i]
        cur_k = k
        cur_i = end_i
        valid = True
        while cur_k > 1:
            l_i = indexed[cur_i][1]
            w_i = indexed[cur_i][2]
